/// Like [`init_tracing_with`], with a sampler override, extra span processors and extra
/// propagators (see [`PipelineOptions`]).
pub fn init_tracing_with_pipeline<E, F>(
    config: TracingConfig,
    exporter_factory: F,
    options: PipelineOptions,
) -> Result<TracingHandle>
where
    E: SpanExporter + 'static,
    F: FnOnce(&TracingConfig) -> Result<E>,
{
    config.validate()?;
    tokio::runtime::Handle::try_current()
        .map_err(|_| Error::config("init_tracing must be called inside a tokio runtime"))?;
    let propagator = Arc::new(build_propagator(&config.propagators, options.propagators)?);
    let exporter = exporter_factory(&config)?;
    let batch = BatchConfigBuilder::default()
        .with_max_queue_size(config.batch.max_queue_size)
        .with_max_export_batch_size(config.batch.max_export_batch_size)
        .with_scheduled_delay(config.batch.scheduled_delay)
        .with_max_export_timeout(config.batch.export_timeout)
        .build();
    let processor = BatchSpanProcessor::builder(exporter, Tokio)
        .with_batch_config(batch)
        .build();
    let sampler = options
        .sampler
        .unwrap_or_else(|| build_sampler(config.sampler, config.sampler_ratio));
    let mut builder = SdkTracerProvider::builder()
        .with_span_processor(processor)
        .with_sampler(sampler)
        .with_resource(build_resource(&config));
    for extra in options.span_processors {
        builder = builder.with_span_processor(BoxedSpanProcessor(extra));
    }
    let provider = builder.build();
    if config.set_global {
        opentelemetry::global::set_tracer_provider(provider.clone());
        opentelemetry::global::set_text_map_propagator(SharedPropagator(Arc::clone(&propagator)));
    }
    Ok(TracingHandle::new(
        provider,
        propagator,
        config.service_name,
    ))
}

